content.content:
# Add a person to a sheet. Validate first so a blank name or a bad grade is a 400, and a name already in use is a 409.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.person.ValidatePerson
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: build
build:
  class: net.officefloor.hq.app.person.BuildPerson
  govern: [ transaction ]
  next: check
check:
  class: net.officefloor.hq.app.person.CheckPersonName
  govern: [ transaction ]
  next: contact
# A contact another person on the sheet already has is a 409.
contact:
  class: net.officefloor.hq.app.person.CheckPersonContact
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.person.SavePerson
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.person.AuditPersonAdded
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
# Paste claims: a DRAFT claim per line of name,amount,date,note for the named person, in order. One
# change: every line is checked by the claim form's rules before anything is written, so a refused
# line refuses the whole paste. A bad line is a 400.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.paste.ValidatePaste
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: add
# Checks every line, then saves, logs and audits each claim (CLAIM_ADDED) in order.
add:
  class: net.officefloor.hq.app.claim.AddPastedClaims
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.paste.RespondWithPaste
  govern: [ transaction ]
package net.officefloor.hq.app.person;

/**
 * A person as the screen sends it, to add or to edit: a name, a grade (A, B or C) and the date the
 * grade is from (yyyy-MM-dd; blank for the sheet's today). An edit also names the version of the
 * person it was made from. A contact is any text (blank: none). Their own terms are a whole number of days, 0 or more (blank: none).
 */
public record PersonRequest(String name, String grade, Long version, String gradeFrom, String terms, String contact) {
    /** The terms as a number of days; null when blank. */
    public Integer termsDays() { return terms == null || terms.isEmpty() ? null : Integer.valueOf(terms); }

    /** The contact as stored: trimmed and lower-cased; null when blank (none). */
    public String contactValue() {
        String c = contact == null ? "" : contact.trim().toLowerCase(java.util.Locale.ROOT);
        return c.isEmpty() ? null : c;
    }

    /** A person's name as the form takes it: trimmed, required, at most 200 characters. */
    public static String checkName(String raw) throws InvalidPersonException {
        String name = raw == null ? "" : raw.trim();
        if (name.isEmpty()) throw new InvalidPersonException("A name is required");
        if (name.length() > 200) throw new InvalidPersonException("A name is at most 200 characters");
        return name;
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePerson {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> body)
            throws InvalidPersonException {
        String name = PersonRequest.checkName(request == null ? null : request.name());
        String grade = request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) throw new InvalidPersonException("A grade is one of A, B or C");
        String gradeFrom = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        if (!gradeFrom.isEmpty()) {
            try {
                LocalDate.parse(gradeFrom);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("A from-date is a date, yyyy-MM-dd");
            }
        }
        String terms = request.terms() == null ? "" : request.terms().trim();
        if (!terms.isEmpty() && !terms.matches("\\d{1,6}")) {
            throw new InvalidPersonException("Terms are a whole number of days, 0 or more, or blank");
        }
        if (!terms.isEmpty()) terms = String.valueOf(Integer.parseInt(terms));
        String contact = request.contact() == null ? "" : request.contact().trim().toLowerCase(java.util.Locale.ROOT);
        if (contact.length() > 200) throw new InvalidPersonException("A contact is at most 200 characters");
        body.set(new PersonRequest(name, grade, request.version(), gradeFrom, terms, contact));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class BuildPerson {
    public void build(@Val PersonRequest request, @Val Sheet sheet, Out<Person> personOut) {
        Person person = new Person(null, sheet.id(), request.name(), request.grade());
        person.setTerms(request.termsDays());
        person.setContact(request.contactValue());
        personOut.set(person);
    }
}
package net.officefloor.hq.app.person;

import java.util.Set;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/**
 * Refuses a person whose name another person on the sheet already has, or whose name or any alias is
 * a name or alias on another sheet of the sheet's tree (so a person who clashes is refused every edit
 * until it leaves them clashing no more).
 */
public class CheckPersonName {
    public void check(@Val Person person, PersonRepository repository, SheetRepository sheets)
            throws DuplicatePersonNameException {
        if (repository.nameTaken(person.getSheetId(), person.getName(), person.getId())) {
            throw new DuplicatePersonNameException(person.getName());
        }
        Set<String> tree = sheets.tree(person.getSheetId());
        if (repository.nameTakenIn(tree, person.getName(), person.getId())) {
            throw new DuplicatePersonNameException(person.getName());
        }
        for (String alias : person.getAliases()) {
            if (repository.nameTakenIn(tree, alias, person.getId())) throw new DuplicatePersonNameException(alias);
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

/** Refuses a person whose contact another person on the sheet already has. A person with no contact passes. */
public class CheckPersonContact {
    public void check(@Val Person person, PersonRepository repository)
            throws DuplicatePersonContactException {
        if (person.getContact() != null
                && repository.contactTaken(person.getSheetId(), person.getContact(), person.getId())) {
            throw new DuplicatePersonContactException(person.getContact());
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

public class SavePerson {
    public void save(@Val Person person, PersonRepository repository) throws StalePersonException {
        if (!repository.save(person)) throw new StalePersonException(String.valueOf(person.getId()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import jakarta.servlet.http.HttpServletRequest;

/** Records the saved person. Runs after every rule has passed, so a refused change writes nothing. */
public class AuditPersonAdded {
    public void audit(@Val Sheet sheet, @Val Person person,
            HttpServletRequest request, Audit audit) {
        audit.record("PERSON_ADDED sheet=" + sheet.id() + " by=" + Audit.user(request)
                + " name=" + person.getName() + " grade=" + person.getGrade()
                + (person.getTerms() == null ? "" : " terms=" + person.getTerms())
                + (person.getContact() == null ? "" : " contact=" + person.getContact()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Sheet sheet, @Val Person person, PersonRepository people, SheetRepository sheets,
            ObjectResponse<PersonResponse> response) {
        boolean clashing = PersonRepository.clashes(person, people.namesIn(sheets.tree(sheet.id())));
        response.send(PersonResponse.from(person, sheet.today(), clashing));
    }
}

